package com.ruoyi.business.ai.capability.project;
import java.util.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Component;import com.ruoyi.business.ai.capability.*;import com.ruoyi.business.domain.BusinessProject;import com.ruoyi.business.service.IBusinessProjectService;import com.ruoyi.common.exception.ServiceException;import static com.ruoyi.business.ai.capability.AiCapabilityInputs.*;
@Component public class TransitionProjectCapability implements AiConfirmableCapability{private static final Set<String>ACTIONS=new LinkedHashSet<String>(Arrays.asList("START_PLANNING","PAUSE","RESUME","CLOSE","CANCEL"));private final IBusinessProjectService service;@Autowired public TransitionProjectCapability(IBusinessProjectService s){service=s;}public String code(){return "project.transition";}public String description(){return "让项目进入规划、暂停、恢复、直接关闭或取消。计划审批和验收结项使用专用审核工具。必须提供稳定项目ID，确认后执行。";}public String requiredPermission(){return "business:project:manage";}public Map<String,Object> inputSchema(){Map<String,Object>s=AiSchemas.object();AiSchemas.property(s,"projectId","number","项目ID");Map<String,Object>a=AiSchemas.property(s,"action","string","START_PLANNING/PAUSE/RESUME/CLOSE/CANCEL");a.put("enum",new ArrayList<String>(ACTIONS));AiSchemas.property(s,"comment","string","暂停、关闭、取消时必须填写原因或结论");return AiSchemas.required(s,"projectId","action");}
 public String confirmationSummary(AiCapabilityInvocation i,Map<String,Object>in){String a=upper(in.get("action"));if(!ACTIONS.contains(a))throw new ServiceException("不支持的项目状态操作");BusinessProject p=service.getProject(number(in.get("projectId")),i.getActor().getUserId(),i.getActor().isAdministrator(),true);if(("PAUSE".equals(a)||"CLOSE".equals(a)||"CANCEL".equals(a))&&text(in.get("comment")).isEmpty())throw new ServiceException("请说明操作原因或完成结论");return label(a)+"项目“"+p.getProjectName()+"”"+(text(in.get("comment")).isEmpty()?"":"，说明："+text(in.get("comment")));}
 public Map<String,Object> executeConfirmed(AiCapabilityInvocation i,Map<String,Object>in){String a=upper(in.get("action"));BusinessProject p=service.transition(number(in.get("projectId")),a,text(in.get("comment")),i.getActor().getUserId(),i.getActor().getUserName(),true);Map<String,Object>r=new LinkedHashMap<String,Object>();r.put("projectId",p.getProjectId());r.put("projectName",p.getProjectName());r.put("action",a);r.put("status",p.getStatus());return r;}private String label(String a){if("START_PLANNING".equals(a))return "推进到规划";if("PAUSE".equals(a))return "暂停";if("RESUME".equals(a))return "恢复";if("CLOSE".equals(a))return "直接关闭";return "取消";}}
